```yaml
- ansible.builtin.pip: {name: bottle==0.11}
- ansible.builtin.pip:
    name: [django>1.11.0,<1.12.0, bottle>0.10,<0.20,!=0.11]
- ansible.builtin.pip: {name: six}
  environment:
    https_proxy: 'https://127.0.0.1:8080'
- ansible.builtin.pip: {name: git+http://myrepo/app/MyApp}
- ansible.builtin.pip: {name: file:///path/to/MyApp.tar.gz}
- ansible.builtin.pip: {name: bottle, virtualenv: /my_app/venv, virtualenv_command: virtualenv-3.13}
- ansible.builtin.pip: {name: bottle, extra_args: --user}
```
